import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.DQQHyi2x.js";const h=JSON.parse('{"title":"Codex Usage/Context Parity Investigation","description":"","frontmatter":{},"headers":[],"relativePath":"plans/2026-05-26-codex-usage-context-investigation.md","filePath":"plans/2026-05-26-codex-usage-context-investigation.md"}'),i={name:"plans/2026-05-26-codex-usage-context-investigation.md"};function n(d,e,c,r,l,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="codex-usage-context-parity-investigation" tabindex="-1">Codex Usage/Context Parity Investigation <a class="header-anchor" href="#codex-usage-context-parity-investigation" aria-label="Permalink to &quot;Codex Usage/Context Parity Investigation&quot;">​</a></h1><p>Date: 2026-05-26 Issue: #142</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Codex usage and context parity should stay diagnostics-only for now. The local Codex files observed on this machine do not expose a stable token usage or context-window metric surface that is safe to treat like Claude Code usage and context data.</p><p>The backend now exposes a read-only Codex diagnostics endpoint:</p><ul><li><code>GET /api/v1/providers/codex-cli/usage-context-diagnostics</code></li></ul><p>This endpoint returns file-shape metadata and an explicit unsupported decision. It does not return prompt text, raw history rows, raw model cache payloads, session ids, model ids, auth data, or cache contents.</p><h2 id="safe-observations" tabindex="-1">Safe Observations <a class="header-anchor" href="#safe-observations" aria-label="Permalink to &quot;Safe Observations&quot;">​</a></h2><p>Observed local Codex files:</p><ul><li><code>history.jsonl</code>: JSONL rows include keys such as <code>session_id</code>, <code>ts</code>, and <code>text</code>. The <code>text</code> field is prompt content and must be treated as sensitive.</li><li><code>models_cache.json</code>: root keys include metadata such as <code>fetched_at</code>, <code>etag</code>, <code>client_version</code>, and <code>models</code>. The model list is cache data rather than a usage ledger.</li></ul><p>The diagnostics endpoint reports counts, root keys, file sizes, parse status, and whether metric-like key names are present. It intentionally omits values for sensitive or opaque fields.</p><h2 id="product-implication" tabindex="-1">Product Implication <a class="header-anchor" href="#product-implication" aria-label="Permalink to &quot;Product Implication&quot;">​</a></h2><p>Claude Code usage and context pages remain Claude-specific. Codex should not be shown as having usage or context parity until a stable local or CLI-backed Codex metric source exists that can be read without exposing prompt text or raw cache payloads.</p>',13)])])}const x=t(i,[["render",n]]);export{h as __pageData,x as default};
